import sys

def countOfSubstrings(S, K):
    count = 0
    char_count = [0] * 26
    distinct = 0

    for i in range(len(S)):
        if char_count[ord(S[i]) - ord('a')] == 0:
            distinct += 1
        char_count[ord(S[i]) - ord('a')] += 1

        if i >= K:
            char_count[ord(S[i - K]) - ord('a')] -= 1
            if char_count[ord(S[i - K]) - ord('a')] == 0:
                distinct -= 1

        if i >= K - 1 and distinct == K - 1:
            count += 1

    return count

input = sys.stdin.read().strip().split()
S = input[0]
K = int(input[1])
print(countOfSubstrings(S, K))
